import argparse

from fastapi import FastAPI, Header, HTTPException
from pydantic import BaseModel, Field

from app.rules import order_rules
from app.store import orders, refunds, settlements
from app.store.db import connect, migrate

app = FastAPI(title="settlement-ledger")

class OrderIn(BaseModel):
    tenant: str = Field(min_length=1)
    order_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)
    currency: str = Field(min_length=3, max_length=3)

class PaymentIn(BaseModel):
    amount_cents: int = Field(gt=0)

class RefundIn(BaseModel):
    refund_id: str = Field(min_length=1)
    order_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)

class SettlementIn(BaseModel):
    settlement_id: str = Field(min_length=1)
    order_id: str = Field(min_length=1)
    amount_cents: int = Field(gt=0)

def _require_tenant(x_tenant: str) -> str:
    if not x_tenant:
        raise HTTPException(status_code=400, detail="tenant header is required")
    return x_tenant

@app.get("/health")
def health() -> dict:
    conn = connect()
    try:
        conn.execute("SELECT 1")
    finally:
        conn.close()
    return {"status": "ok"}

@app.post("/orders", status_code=201)
def create_order(body: OrderIn) -> dict:
    order_rules.assert_currency(body.currency)
    try:
        orders.insert(body.tenant, body.order_id, body.amount_cents, body.currency)
    except Exception as error:
        if "UNIQUE" in str(error):
            raise HTTPException(status_code=409, detail="order already accepted")
        raise
    return orders.get(body.tenant, body.order_id)

@app.get("/orders/{order_id}")
def read_order(order_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    order = orders.get(tenant, order_id)
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/orders/{order_id}/payments")
def add_payment(order_id: str, body: PaymentIn, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    try:
        order = orders.add_payment(tenant, order_id, body.amount_cents)
    except ValueError as error:
        raise HTTPException(status_code=409, detail=str(error))
    if order is None:
        raise HTTPException(status_code=404, detail="order not found")
    return order

@app.post("/refunds", status_code=201)
def accept_refund(body: RefundIn, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    try:
        result, refund = refunds.accept(tenant, body.refund_id, body.order_id, body.amount_cents)
    except refunds.OrderNotSettled:
        # 未收金额不为 0：订单尚未结清
        raise HTTPException(status_code=409, detail="order is not settled")
    except refunds.RefundExceedsBalance:
        # 超过 可退余额 = 订单金额 − 累计已退金额
        raise HTTPException(status_code=409, detail="refund exceeds refundable amount")
    if result == "order_not_found":
        # 订单不存在或属于其他租户，一律按不存在处理
        raise HTTPException(status_code=404, detail="order not found")
    if result == "duplicate":
        # 幂等：重复受理命中首次受理结论，不二次入账
        raise HTTPException(status_code=409, detail="refund already accepted")
    if result == "already_reversed":
        # 已冲正的退款单标识不得再次受理
        raise HTTPException(status_code=409, detail="refund already reversed")
    return refund

@app.get("/refunds/{refund_id}")
def read_refund(refund_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    refund = refunds.get(tenant, refund_id)
    if refund is None:
        raise HTTPException(status_code=404, detail="refund not found")
    return refund

@app.post("/refunds/{refund_id}/reverse")
def reverse_refund(refund_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    try:
        refund = refunds.reverse(tenant, refund_id)
    except refunds.RefundAlreadyReversed:
        raise HTTPException(status_code=409, detail="refund already reversed")
    if refund is None:
        # 标识未受理或属于其他租户，一律按不存在处理
        raise HTTPException(status_code=404, detail="refund not found")
    return refund

# ---------- 结算单（独立单据，租户同样通过请求头 X-Tenant 声明） ----------

@app.post("/settlements", status_code=201)
def accept_settlement(body: SettlementIn, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    try:
        result, settlement = settlements.accept(
            tenant, body.settlement_id, body.order_id, body.amount_cents
        )
    except settlements.OrderNotSettled:
        # 未收金额不为 0：订单尚未结清
        raise HTTPException(status_code=409, detail="order is not settled")
    except settlements.OrderHasRefunds:
        # 累计已退金额不为 0：订单已发生退款
        raise HTTPException(status_code=409, detail="order has refunds")
    except settlements.SettlementExceedsBalance:
        # 超过 剩余可结算金额 = 订单金额 − 已受理结算金额之和（不含已冲正部分）
        raise HTTPException(status_code=409, detail="settlement exceeds settleable amount")
    if result == "order_not_found":
        # 订单不存在或属于其他租户，一律按不存在处理
        raise HTTPException(status_code=404, detail="order not found")
    if result == "duplicate":
        # 幂等：重复受理命中首次受理结论，不二次入账
        raise HTTPException(status_code=409, detail="settlement already accepted")
    if result == "already_reversed":
        # 已冲正的结算单标识不得再次受理
        raise HTTPException(status_code=409, detail="settlement already reversed")
    return settlement

@app.get("/settlements/{settlement_id}")
def read_settlement(settlement_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    settlement = settlements.get(tenant, settlement_id)
    if settlement is None:
        raise HTTPException(status_code=404, detail="settlement not found")
    return settlement

@app.post("/settlements/{settlement_id}/payments")
def add_settlement_payment(
    settlement_id: str, body: PaymentIn, x_tenant: str = Header(default="")
) -> dict:
    tenant = _require_tenant(x_tenant)
    try:
        settlement = settlements.add_payment(tenant, settlement_id, body.amount_cents)
    except settlements.PaymentExceedsUnreceived:
        # 累计收款不得超过结算金额
        raise HTTPException(status_code=409, detail="payment exceeds unreceived amount")
    except settlements.SettlementAlreadyReversed:
        raise HTTPException(status_code=409, detail="settlement already reversed")
    if settlement is None:
        # 标识未受理或属于其他租户，一律按不存在处理
        raise HTTPException(status_code=404, detail="settlement not found")
    return settlement

@app.post("/settlements/{settlement_id}/reverse")
def reverse_settlement(settlement_id: str, x_tenant: str = Header(default="")) -> dict:
    tenant = _require_tenant(x_tenant)
    try:
        settlement = settlements.reverse(tenant, settlement_id)
    except settlements.SettlementAlreadyReversed:
        raise HTTPException(status_code=409, detail="settlement already reversed")
    except settlements.SettlementHasPayments:
        # 存在任何收款时不允许冲正
        raise HTTPException(status_code=409, detail="settlement has payments")
    if settlement is None:
        # 标识未受理或属于其他租户，一律按不存在处理
        raise HTTPException(status_code=404, detail="settlement not found")
    return settlement

def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=8000)
    parser.add_argument("--migrate", action="store_true")
    args = parser.parse_args()
    migrate()
    if args.migrate:
        print("migrated")
        return
    import uvicorn
    uvicorn.run(app, host="127.0.0.1", port=args.port)

if __name__ == "__main__":
    main()

import sqlite3

from app.store.db import connect


def insert(tenant: str, order_id: str, amount_cents: int, currency: str) -> None:
    conn = connect()
    try:
        conn.execute(
            "INSERT INTO orders(tenant, order_id, amount_cents, paid_cents, currency, status) VALUES(?,?,?,0,?,'accepted')",
            (tenant, order_id, amount_cents, currency),
        )
    finally:
        conn.close()

def get(tenant: str, order_id: str) -> dict | None:
    conn = connect()
    try:
        row = conn.execute(
            "SELECT tenant, order_id, amount_cents, paid_cents, refunded_cents, settled_cents, currency, status "
            "FROM orders WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
    finally:
        conn.close()
    if row is None:
        return None
    return order_view(row)

def order_view(row: sqlite3.Row) -> dict:
    amount = row["amount_cents"]
    outstanding = amount - row["paid_cents"]
    refundable = amount - row["refunded_cents"]
    settleable = amount - row["settled_cents"]
    return {
        **dict(row),
        "outstanding_cents": outstanding,
        "refundable_cents": refundable,
        "settleable_cents": settleable,
    }

def add_payment(tenant: str, order_id: str, amount_cents: int) -> dict | None:
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT amount_cents, paid_cents, refunded_cents FROM orders WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
        if row is None:
            conn.execute("ROLLBACK")
            return None
        if amount_cents <= 0 or row["paid_cents"] + amount_cents > row["amount_cents"]:
            conn.execute("ROLLBACK")
            raise ValueError("payment exceeds outstanding amount")
        conn.execute(
            "UPDATE orders SET paid_cents = paid_cents + ?, status = CASE WHEN paid_cents + ? >= amount_cents THEN 'settled' ELSE 'accepted' END WHERE tenant=? AND order_id=?",
            (amount_cents, amount_cents, tenant, order_id),
        )
        conn.execute("COMMIT")
    finally:
        conn.close()
    return get(tenant, order_id)

import sqlite3
from datetime import UTC, datetime

from app.store.db import connect


class OrderNotSettled(Exception):
    """订单未结清（未收金额不为 0），不能受理结算单。"""


class OrderHasRefunds(Exception):
    """订单已发生退款（累计已退金额不为 0），不能受理结算单。"""


class SettlementExceedsBalance(Exception):
    """结算金额超过订单剩余可结算金额（订单金额 − 已受理结算金额之和）。"""


class SettlementAlreadyReversed(Exception):
    """结算单已处于已冲正状态，不能重复冲正。"""


class SettlementHasPayments(Exception):
    """结算单已存在收款（累计已收不为 0），不能冲正。"""


class PaymentExceedsUnreceived(Exception):
    """本次收款会使累计已收超过结算金额。"""


def _now() -> str:
    return datetime.now(UTC).isoformat(timespec="seconds")


_DOC_COLUMNS = (
    "tenant, settlement_id, order_id, amount_cents, received_cents, currency, "
    "status, created_at, reversed_at"
)


def _settlement_view(row: sqlite3.Row) -> dict:
    return {
        **dict(row),
        "unreceived_cents": row["amount_cents"] - row["received_cents"],
    }


def get(tenant: str, settlement_id: str) -> dict | None:
    conn = connect()
    try:
        row = conn.execute(
            f"SELECT {_DOC_COLUMNS} FROM settlements WHERE tenant=? AND settlement_id=?",
            (tenant, settlement_id),
        ).fetchone()
    finally:
        conn.close()
    return None if row is None else _settlement_view(row)


def accept(tenant: str, settlement_id: str, order_id: str, amount_cents: int) -> tuple[str, dict | None]:
    """受理结算单。

    返回 (结论, 结算单视图)，结论为 accepted / duplicate / already_reversed；
    订单不存在（含跨租户）返回 order_not_found；业务校验失败抛出可区分的异常。
    判重、订单校验、单据落库、订单累计已结算更新在单个立即事务内完成：
    并发下同一标识最多一个 accepted，不同单据累计已结算不会超过订单剩余可结算金额；
    任何失败都回滚，不留部分数据。
    """
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = conn.execute(
            f"SELECT {_DOC_COLUMNS} FROM settlements WHERE tenant=? AND settlement_id=?",
            (tenant, settlement_id),
        ).fetchone()
        if existing is not None:
            # 幂等：重复受理不重复入账，也不改变首次受理的单据；
            # 已冲正的标识不得再次受理
            conn.execute("ROLLBACK")
            result = "already_reversed" if existing["status"] == "reversed" else "duplicate"
            return result, _settlement_view(existing)

        order = conn.execute(
            "SELECT amount_cents, paid_cents, refunded_cents, settled_cents, currency FROM orders "
            "WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
        if order is None:
            # 跨租户或不存在一律按“不存在”处理，不泄漏订单是否存在
            conn.execute("ROLLBACK")
            return "order_not_found", {}

        if order["amount_cents"] - order["paid_cents"] > 0:
            conn.execute("ROLLBACK")
            raise OrderNotSettled("order is not settled")

        if order["refunded_cents"] != 0:
            conn.execute("ROLLBACK")
            raise OrderHasRefunds("order has refunds")

        # 剩余可结算金额 = 订单金额 − 已受理结算金额之和（已冲正部分已整体释放）
        if amount_cents > order["amount_cents"] - order["settled_cents"]:
            conn.execute("ROLLBACK")
            raise SettlementExceedsBalance("settlement exceeds settleable amount")

        created_at = _now()
        conn.execute(
            "INSERT INTO settlements(tenant, settlement_id, order_id, amount_cents, received_cents, "
            "currency, status, created_at) VALUES(?,?,?,?,0,?,'accepted',?)",
            (tenant, settlement_id, order_id, amount_cents, order["currency"], created_at),
        )
        # 只改写订单累计已结算金额；paid_cents/收款记录/refunded_cents 一律不动
        conn.execute(
            "UPDATE orders SET settled_cents = settled_cents + ? WHERE tenant=? AND order_id=?",
            (amount_cents, tenant, order_id),
        )
        conn.execute("COMMIT")
    finally:
        conn.close()
    return "accepted", get(tenant, settlement_id)


def add_payment(tenant: str, settlement_id: str, amount_cents: int) -> dict | None:
    """登记一笔分期收款；累计已收不得超过结算金额。

    结算单不存在（含跨租户）返回 None；已冲正抛出 SettlementAlreadyReversed；
    超限抛出 PaymentExceedsUnreceived。判定与入账在单个立即事务内完成。
    """
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT amount_cents, received_cents, status FROM settlements WHERE tenant=? AND settlement_id=?",
            (tenant, settlement_id),
        ).fetchone()
        if row is None:
            conn.execute("ROLLBACK")
            return None
        if row["status"] == "reversed":
            conn.execute("ROLLBACK")
            raise SettlementAlreadyReversed("settlement already reversed")
        if amount_cents <= 0 or row["received_cents"] + amount_cents > row["amount_cents"]:
            conn.execute("ROLLBACK")
            raise PaymentExceedsUnreceived("payment exceeds unreceived amount")
        conn.execute(
            "UPDATE settlements SET received_cents = received_cents + ? WHERE tenant=? AND settlement_id=?",
            (amount_cents, tenant, settlement_id),
        )
        conn.execute("COMMIT")
    finally:
        conn.close()
    return get(tenant, settlement_id)


def reverse(tenant: str, settlement_id: str) -> dict | None:
    """冲正已受理且累计已收为 0 的结算单；整体释放占用的订单剩余结算金额。

    结算单不存在（含跨租户）返回 None；已冲正抛出 SettlementAlreadyReversed；
    存在任何收款抛出 SettlementHasPayments。判定与入账在单个立即事务内完成。
    """
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT amount_cents, received_cents, order_id, status FROM settlements "
            "WHERE tenant=? AND settlement_id=?",
            (tenant, settlement_id),
        ).fetchone()
        if row is None:
            conn.execute("ROLLBACK")
            return None
        if row["status"] == "reversed":
            conn.execute("ROLLBACK")
            raise SettlementAlreadyReversed("settlement already reversed")
        if row["received_cents"] != 0:
            conn.execute("ROLLBACK")
            raise SettlementHasPayments("settlement has payments")

        reversed_at = _now()
        conn.execute(
            "UPDATE settlements SET status='reversed', reversed_at=? WHERE tenant=? AND settlement_id=?",
            (reversed_at, tenant, settlement_id),
        )
        conn.execute(
            "UPDATE orders SET settled_cents = settled_cents - ? WHERE tenant=? AND order_id=?",
            (row["amount_cents"], tenant, row["order_id"]),
        )
        conn.execute("COMMIT")
    finally:
        conn.close()
    return get(tenant, settlement_id)

import sqlite3
from datetime import UTC, datetime

from app.store.db import connect


class OrderNotSettled(Exception):
    """订单未结清（未收金额不为 0），不能受理退款。"""


class RefundExceedsBalance(Exception):
    """退款金额超过可退余额（订单金额 − 累计已退金额）。"""


class RefundAlreadyReversed(Exception):
    """退款单已处于已冲正状态，不能重复冲正。"""


def _now() -> str:
    return datetime.now(UTC).isoformat(timespec="seconds")


def _refund_view(row: sqlite3.Row) -> dict:
    return dict(row)


def get(tenant: str, refund_id: str) -> dict | None:
    conn = connect()
    try:
        row = conn.execute(
            "SELECT tenant, refund_id, order_id, amount_cents, currency, status, created_at, reversed_at "
            "FROM refunds WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        ).fetchone()
    finally:
        conn.close()
    return None if row is None else _refund_view(row)


def accept(tenant: str, refund_id: str, order_id: str, amount_cents: int) -> tuple[str, dict | None]:
    """受理退款单。

    返回 (结论, 退款单视图)，结论为 accepted / duplicate。
    订单不存在（含跨租户）返回键不存在；业务校验失败抛出可区分的异常。
    整个判定与入账在一个立即事务内完成：并发下最多一个 accepted，
    任何失败都回滚，不留部分数据。
    """
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        existing = conn.execute(
            "SELECT tenant, refund_id, order_id, amount_cents, currency, status, created_at, reversed_at "
            "FROM refunds WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        ).fetchone()
        if existing is not None:
            # 幂等：重复受理不重复入账，也不改变首次受理的单据；
            # 已冲正的标识不得再次受理
            conn.execute("ROLLBACK")
            result = "already_reversed" if existing["status"] == "reversed" else "duplicate"
            return result, _refund_view(existing)

        order = conn.execute(
            "SELECT amount_cents, paid_cents, refunded_cents, currency FROM orders "
            "WHERE tenant=? AND order_id=?",
            (tenant, order_id),
        ).fetchone()
        if order is None:
            # 跨租户或不存在一律按“不存在”处理，不泄漏订单是否存在
            conn.execute("ROLLBACK")
            return "order_not_found", {}

        if order["amount_cents"] - order["paid_cents"] > 0:
            conn.execute("ROLLBACK")
            raise OrderNotSettled("order is not settled")

        if amount_cents > order["amount_cents"] - order["refunded_cents"]:
            conn.execute("ROLLBACK")
            raise RefundExceedsBalance("refund exceeds refundable amount")

        created_at = _now()
        conn.execute(
            "INSERT INTO refunds(tenant, refund_id, order_id, amount_cents, currency, status, created_at) "
            "VALUES(?,?,?,?,?,'accepted',?)",
            (tenant, refund_id, order_id, amount_cents, order["currency"], created_at),
        )
        # 只改写累计已退金额；paid_cents 与收款记录保持不动
        conn.execute(
            "UPDATE orders SET refunded_cents = refunded_cents + ? WHERE tenant=? AND order_id=?",
            (amount_cents, tenant, order_id),
        )
        conn.execute("COMMIT")
    finally:
        conn.close()
    return "accepted", get(tenant, refund_id)


def reverse(tenant: str, refund_id: str) -> dict | None:
    """冲正已受理的退款单；整体退回累计已退金额。

    退款单不存在（含跨租户）返回 None；已冲正抛出 RefundAlreadyReversed。
    """
    conn = connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        row = conn.execute(
            "SELECT amount_cents, order_id, status FROM refunds WHERE tenant=? AND refund_id=?",
            (tenant, refund_id),
        ).fetchone()
        if row is None:
            conn.execute("ROLLBACK")
            return None
        if row["status"] == "reversed":
            conn.execute("ROLLBACK")
            raise RefundAlreadyReversed("refund already reversed")

        reversed_at = _now()
        conn.execute(
            "UPDATE refunds SET status='reversed', reversed_at=? WHERE tenant=? AND refund_id=?",
            (reversed_at, tenant, refund_id),
        )
        conn.execute(
            "UPDATE orders SET refunded_cents = refunded_cents - ? WHERE tenant=? AND order_id=?",
            (row["amount_cents"], tenant, row["order_id"]),
        )
        conn.execute("COMMIT")
    finally:
        conn.close()
    return get(tenant, refund_id)

import os
import tempfile

os.environ.setdefault("APP_DB", os.path.join(tempfile.mkdtemp(), "test.sqlite"))
from fastapi.testclient import TestClient

from app.entry import app
from app.store.db import migrate

migrate()
client = TestClient(app)

def test_accept_and_read_order() -> None:
    body = {"tenant": "t1", "order_id": "o1", "amount_cents": 500, "currency": "CNY"}
    assert client.post("/orders", json=body).status_code == 201
    got = client.get("/orders/o1", headers={"X-Tenant": "t1"})
    assert got.status_code == 200 and got.json()["outstanding_cents"] == 500

def test_duplicate_is_refused() -> None:
    body = {"tenant": "t1", "order_id": "o2", "amount_cents": 100, "currency": "CNY"}
    assert client.post("/orders", json=body).status_code == 201
    assert client.post("/orders", json=body).status_code == 409

def test_cross_tenant_read_is_not_found() -> None:
    body = {"tenant": "t1", "order_id": "o3", "amount_cents": 100, "currency": "CNY"}
    client.post("/orders", json=body)
    assert client.get("/orders/o3", headers={"X-Tenant": "t2"}).status_code == 404

def test_payment_cannot_exceed_outstanding() -> None:
    body = {"tenant": "t1", "order_id": "o4", "amount_cents": 300, "currency": "CNY"}
    client.post("/orders", json=body)
    assert client.post("/orders/o4/payments", json={"amount_cents": 100}, headers={"X-Tenant": "t1"}).status_code == 200
